USE portfolio;

SELECT * FROM customer_data LIMIT 10;

--Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) as Revenue
FROM customer_data
GROUP BY gender

--Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer_data
WHERE discount_applied = 'Yes' and purchase_amount >= (SELECT AVG(purchase_amount) as average_purchase_amount FROM customer_data)

--Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased, AVG(review_rating) as average_rating
FROM customer_data
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT shipping_type, ROUND(AVG(purchase_amount),2)
FROM customer_data
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type

--Q5. Do subscribed customers spend more? 
--Compare average spend and total revenue between subscribers and non-subscribers.

SELECT COUNT(customer_id) as total_customer, AVG(purchase_amount) as average_spend, SUM(purchase_amount) as total_revenue, subscription_status
FROM customer_data
GROUP BY subscription_status
ORDER BY average_spend, total_revenue;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased, SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) * 100 / COUNT(*) as discount_rate
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

--Q7. Segment customers into New, Returning, 
--and Loyal based on their total number of previous purchases, and show the count of each segment.
WITH customer_type AS(
    SELECT customer_id , previous_purchases, 
    CASE 
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END as customer_segment
FROM customer_data
)
SELECT customer_segment, count(*) as total_customer
FROM customer_type
GROUP BY customer_segment


--Q8. What are the top 3 most purchased products within each category?
WITH item_counts AS(
    SELECT category, item_purchased,
    COUNT(customer_id) AS total_items,
    ROW_NUMBER() OVER ( PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer_data
    GROUP BY category, item_purchased
)

SELECT * FROM item_counts
WHERE item_rank <= 3;